const SKIP_EXTRACT = process.argv.includes("--skip-extract");
const SOURCES_FILTER = process.argv.find((a) => a.startsWith("--sources="))?.slice(10);
const FROM_PROJECT = process.argv.find((a) => a.startsWith("--from-project="))?.slice(15) || null;
const REPAIR_PROJECTS =
  process.argv
    .find((a) => a.startsWith("--repair-projects="))
    ?.slice(18)
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean) || [];
const SKIP_DISTILL_IF_READY = process.argv.includes("--skip-distill-if-ready");

const ACTIVE_SOURCES = SOURCES_FILTER
  ? SOURCES_FILTER.split(",")
      .map((k) => SOURCES.find((s) => s.key === k.trim()))
      .filter(Boolean)
  : SOURCES;

function run(script, args = [], env = {}) {
  const r = spawnSync(NODE, [path.join(BASE, script), ...args], {
    cwd: BASE,
    encoding: "utf8",
    env: { ...process.env, ...env },
    stdio: ["ignore", "inherit", "inherit"],
    maxBuffer: 50 * 1024 * 1024,
  });
  return r;
}

