function runProjectPipeline(key, project, sessN, distillRoot, srcState) {
  console.log(`\n--- ${project} (${sessN} sessions) ---`);
  const memExisting = countMemories(distillRoot, project);
  if (SKIP_DISTILL_IF_READY && memExisting > 0) {
    console.log(`  已有 ${memExisting} 条 distill 草稿，跳过 bundle/distill`);
  } else {
    const br = run("scripts/build-bundles-multi.mjs", [project], { MM_SOURCE_FILTER: key });
    if (br.status !== 0) {
      console.error("  bundle fail (exit", br.status, ")");
      srcState.details.push({ project, error: "bundle" });
      return;
    }
    const dr = run("scripts/distill-draft.mjs", [project], {
      MM_DISTILL_ROOT: distillRoot,
      MM_SKIP_KNOWN: "1",
    });
    if (dr.status !== 0) {
      console.error("  distill fail (exit", dr.status, ")");
      srcState.details.push({ project, error: "distill" });
      return;
    }
    patchEvidence(distillRoot, key);
  }
  const memN = countMemories(distillRoot, project);
  if (!memN) {
    console.log("  0 条新记忆（可能已被 knownTitles 去重），跳过导入");
    srcState.details.push({ project, memories: 0, skipped: true });
    return;
  }
  const doneFile = path.join(TMP, `done-ov-${key}-${project}.json`);
  const srcDir = path.join(distillRoot, project);
  const ir = run("import-to-ov.mjs", [
    project,
    `--batch=${BATCH}`,
    `--gap=${GAP}`,
    `--src=${srcDir}`,
    `--done=${doneFile}`,
    `--skip=${doneFile}`,
  ]);
  if (ir.status !== 0) {
    srcState.details.push({ project, memories: memN, error: "import", code: ir.status });
  } else {
    srcState.imported++;
    srcState.memories += memN;
    srcState.details.push({ project, memories: memN, ok: true });
  }
}

const allRows = loadSessions();
const state = {
  startedAt: new Date().toISOString(),
  resume: {
    sourcesFilter: SOURCES_FILTER || null,
    fromProject: FROM_PROJECT,
    repairProjects: REPAIR_PROJECTS,
    skipDistillIfReady: SKIP_DISTILL_IF_READY,
  },
  sources: {},
};

for (const { key, label } of ACTIVE_SOURCES) {
  console.log(`\n======== ${label} (${key}) ========`);
  const projs = projectsForSource(allRows, key);
  if (!projs.length) {
    console.log("  无有效项目，跳过");
    state.sources[key] = { skipped: true, reason: "no projects" };
    continue;
  }
  const projMap = new Map(projs);
  const distillRoot = path.join(OUT, "distilled-local", key);
  fs.mkdirSync(distillRoot, { recursive: true });
  const srcState = { projects: projs.length, imported: 0, memories: 0, details: [] };
  const repaired = new Set();

  for (const rp of REPAIR_PROJECTS) {
    if (!projMap.has(rp)) continue;
    console.log(`\n[repair] ${rp}`);
    runProjectPipeline(key, rp, projMap.get(rp), distillRoot, srcState);
    repaired.add(rp);
  }

  let reached = !FROM_PROJECT;
  for (const [project, sessN] of projs) {
    if (FROM_PROJECT) {
      if (!reached) {
        if (project === FROM_PROJECT) reached = true;
        else continue;
      }
    }
    if (repaired.has(project)) continue;
    runProjectPipeline(key, project, sessN, distillRoot, srcState);
  }
  state.sources[key] = srcState;
  console.log(`\n${label} 小结: 项目 ${srcState.imported}/${projs.length} 成功, 约 ${srcState.memories} 条记忆`);
}

